```json
{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-05",
  "sketch": {
    "components": ["Admin Portal", "SAML Handler", "Corporate Identity Provider", "Session Manager", "Role Attribute Parser", "Internet Gateway"],
    "dataStores": ["Session Store", "Audit Log"],
    "externalServices": ["Corporate IdP"],
    "trustBoundaries": ["Internet to DMZ", "DMZ to Internal Network"],
    "dataClasses": ["credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Attacker gains admin access by manipulating role attribute in SAML assertion",
      "scenario": "An attacker with valid employee credentials modifies the role attribute in the SAML response before it reaches the portal, granting themselves admin privileges. If the portal only validates the outer signature but not the specific role attribute, or accepts any attribute name containing 'role', the modified claim is trusted and the attacker gains admin access to the internal portal.",
      "component": "Role Attribute Parser",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "the portal reads the role attribute from the assertion to decide admin access"
        }
      ],
      "asvs": ["V2.7.1"],
      "cwe": ["CWE-285"],
      "plainLanguage": "An attacker could change their role in the login response to become an admin",
      "requirement": {
        "title": "Validate role attribute source and integrity",
        "given": "an employee authenticates via SAML SSO",
        "when": "the portal reads the role attribute from the assertion",
        "then": "the portal must validate the SAML signature covers the role attribute, verify the assertion came from the authorized IdP, and reject assertions with unexpected attribute names or values"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Authentication bypass through SAML signature validation failure",
      "scenario": "An attacker crafts a SAML assertion claiming to be any employee and sends it to the portal. If the portal doesn't properly validate the digital signature against the IdP's certificate, or accepts assertions without signatures, the attacker successfully authenticates as any user, including admins, gaining full access to the internal portal.",
      "component": "SAML Handler",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on with the corporate identity provider"
        }
      ],
      "asvs": ["V2.7.1", "V2.7.2"],
      "cwe": ["CWE-347"],
      "plainLanguage": "An attacker could fake a login response if the system doesn't check it was really signed by the company's login provider",
      "requirement": {
        "title": "Cryptographically validate all SAML assertions",
        "given": "the portal receives a SAML assertion",
        "when": "processing the assertion for authentication",
        "then": "the portal must validate the signature using the IdP's public certificate, reject unsigned assertions, verify the certificate chain, and validate the signature covers all security-relevant elements"
      }
    },
    {
      "stride": "Spoofing",
      "title": "XML signature wrapping attack allows assertion content replacement",
      "scenario": "An attacker intercepts a valid SAML response with a legitimate signature. They create a new assertion with admin roles, then wrap the legitimate signature around it using XML structure manipulation. The portal's XML parser sees the attacker's assertion with admin roles, while the signature validator sees the original signed content, allowing authentication bypass with elevated privileges.",
      "component": "SAML Handler",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "the portal reads the role attribute from the assertion to decide admin access"
        }
      ],
      "asvs": ["V2.7.1"],
      "cwe": ["CWE-290", "CWE-345"],
      "plainLanguage": "An attacker could hide malicious content in the XML structure where signatures don't protect it",
      "requirement": {
        "title": "Prevent XML signature wrapping attacks",
        "given": "the portal receives a signed SAML assertion",
        "when": "validating the signature",
        "then": "the portal must use a SAML library that defends against signature wrapping, validate that signed references match the parsed content exactly, and reject assertions with duplicate IDs or unexpected XML structure"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Missing IdP issuer validation allows authentication via attacker-controlled IdP",
      "scenario": "An attacker sets up their own SAML identity provider that issues assertions with admin roles. When they send these assertions to the portal, if the portal doesn't validate the Issuer field or doesn't restrict which IdPs it accepts assertions from, it processes the attacker's assertion and grants admin access, even though it didn't come from the corporate IdP.",
      "component": "SAML Handler",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on with the corporate identity provider"
        }
      ],
      "asvs": ["V2.7.3"],
      "cwe": ["CWE-346"],
      "plainLanguage": "An attacker could set up their own fake login provider and trick the system into accepting it",
      "requirement": {
        "title": "Validate SAML assertion issuer",
        "given": "the portal receives a SAML assertion",
        "when": "processing authentication",
        "then": "the portal must validate the Issuer field exactly matches the expected corporate IdP entity ID, reject assertions from unknown issuers, and maintain an allowlist of exactly one authorized IdP"
      }
    },
    {
      "stride": "Spoofing",
      "title": "SAML assertion replay allows reuse of stolen authentication tokens",
      "scenario": "An attacker intercepts or steals a valid SAML assertion through network sniffing or malware. The attacker replays this assertion to the portal hours or days later. If the portal doesn't validate NotBefore/NotOnOrAfter timestamps or track assertion IDs to prevent reuse, the attacker successfully authenticates as the victim employee, gaining access until the assertion expires.",
      "component": "SAML Handler",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on"
        },
        {
          "quote": "The portal is reachable from the internet"
        }
      ],
      "asvs": ["V2.7.2"],
      "cwe": ["CWE-294"],
      "plainLanguage": "An attacker who steals a login token could reuse it later to log in as that person",
      "requirement": {
        "title": "Prevent SAML assertion replay",
        "given": "the portal receives a SAML assertion",
        "when": "processing authentication",
        "then": "the portal must validate NotBefore and NotOnOrAfter conditions, maintain a cache of used assertion IDs with appropriate retention, reject assertions with IDs seen before, and enforce a maximum assertion age"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "XML entity expansion attack crashes SAML parser or exhausts memory",
      "scenario": "An attacker sends a SAML response containing a billion laughs attack (nested XML entity expansions) or XML external entity references to large files. When the portal's XML parser processes this malicious SAML response, it expands the entities consuming gigabytes of memory or CPU time, causing the parser to crash, hang, or exhaust server resources, making the admin portal unavailable to legitimate users.",
      "component": "SAML Handler",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on"
        },
        {
          "quote": "The portal is reachable from the internet"
        }
      ],
      "asvs": ["V14.2.1"],
      "cwe": ["CWE-611"],
      "plainLanguage": "An attacker could send a specially crafted XML file that crashes the login system or makes it very slow",
      "requirement": {
        "title": "Protect XML parser from entity attacks",
        "given": "the portal parses SAML XML",
        "when": "receiving a SAML response",
        "then": "the portal must disable XML external entity processing, disable DTD processing, limit entity expansion depth and size, and use a hardened XML parser with these protections enabled by default"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Session fixation allows attacker to hijack authenticated session",
      "scenario": "An attacker tricks an employee into using a session ID the attacker controls through a crafted link with a session parameter. The employee authenticates via SAML using that session. If the portal doesn't regenerate the session ID after successful SAML authentication, the attacker can use the known session ID to access the portal as the authenticated employee, including any admin privileges they have.",
      "component": "Session Manager",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "After login, the portal reads the role attribute from the assertion to decide admin access"
        }
      ],
      "asvs": ["V3.2.1"],
      "cwe": ["CWE-384"],
      "plainLanguage": "An attacker could trick someone into using a login session the attacker knows about, then steal their access",
      "requirement": {
        "title": "Regenerate session after SAML authentication",
        "given": "an employee completes SAML authentication",
        "when": "the portal establishes their authenticated session",
        "then": "the portal must generate a new session ID, invalidate any pre-authentication session ID, transfer necessary session data to the new session, and set secure session cookie attributes"
      }
    },
    {
      "stride": "Tampering",
      "title": "Insufficient TLS validation allows man-in-the-middle attack on SAML exchange",
      "scenario": "An attacker performs a man-in-the-middle attack between the employee's browser and the portal, or between the portal and the IdP. If the portal doesn't validate TLS certificates properly (checking certificate chain, hostname, expiration), the attacker can intercept SAML assertions in transit, modify role attributes to grant admin access, and forward the tampered assertion to the portal, which processes it as legitimate.",
      "component": "SAML Handler",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "The portal is reachable from the internet"
        },
        {
          "quote": "the portal reads the role attribute from the assertion to decide admin access"
        }
      ],
      "asvs": ["V9.2.1"],
      "cwe": ["CWE-295"],
      "plainLanguage": "An attacker on the network could intercept the connection and modify the login information",
      "requirement": {
        "title": "Enforce strong TLS validation",
        "given": "the portal communicates with the IdP or receives SAML assertions",
        "when": "establishing or maintaining connections",
        "then": "the portal must validate TLS certificates against trusted CAs, verify hostname matches, check certificate expiration, enforce TLS 1.2 or higher, and reject connections with invalid certificates"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Insufficient audit logging prevents detection of privilege escalation",
      "scenario": "An attacker successfully exploits a SAML vulnerability to gain admin access, performs malicious actions (viewing sensitive data, changing configurations, creating backdoor accounts), then covers their tracks. Because the portal doesn't log authentication events, role assignments from SAML assertions, or admin actions with sufficient detail, security teams cannot detect the breach, attribute actions to the attacker, or determine the scope of compromise during incident response.",
      "component": "Audit Log",
      "likelihood": 2,
      "impact": 3,
      "evidence": [
        {
          "quote": "the portal reads the role attribute from the assertion to decide admin access"
        }
      ],
      "asvs": ["V7.1.1", "V7.1.2"],
      "cwe": ["CWE-778"],
      "plainLanguage": "If someone breaks in and changes things, there's no record to investigate what happened",
      "requirement": {
        "title": "Log all authentication and authorization events",
        "given": "an employee authenticates via SAML or accesses admin functions",
        "when": "authentication succeeds, fails, or authorization is checked",
        "then": "the portal must log the event with timestamp, user identifier, source IP, roles assigned, assertion ID, and any authorization decisions, retain logs for at least 90 days, and protect logs from tampering"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Detailed SAML error messages leak implementation details to attackers",
      "scenario": "An attacker sends malformed or malicious SAML assertions to probe the portal's implementation. The portal returns detailed error messages revealing the XML parser version, expected assertion structure, attribute names, certificate details, or signature algorithm requirements. The attacker uses this information to craft more effective attacks, targeting known vulnerabilities in the specific parser version or adjusting their forgery attempts to match expected formats.",
      "component": "SAML Handler",
      "likelihood": 2,
      "impact": 2,
      "evidence": [
        {
          "quote": "The portal is reachable from the internet"
        }
      ],
      "asvs": ["V7.4.1"],
      "cwe": ["CWE-209"],
      "plainLanguage": "Error messages could tell an attacker too much about how the login system works",
      "requirement": {
        "title": "Return generic SAML error messages",
        "given": "SAML processing fails",
        "when": "returning an error to the client",
        "then": "the portal must return a generic authentication failure message without revealing signature validation failures, expected values, parser details, or implementation specifics, while logging detailed errors securely for administrators"
      }
    }
  ]
}
```
